CREATE FUNCTION authz_int."workspace__work_all__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."workspace__work_all");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'workspace.work_all = admin or (agent and {open_queue})';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."workspace__admin");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'admin';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."workspace__admin__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "hd"."workspaces" r
  WHERE r."id" IN (SELECT id FROM authz_int."workspace__agent")
    AND coalesce((open_queue), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(agent and {open_queue})';
    v_ok := (p_id) IN (SELECT id FROM authz_int."workspace__agent");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'agent';
    IF v_ok AND v_holds THEN RETURN QUERY SELECT * FROM authz_int."workspace__agent__why"(p_id, p_depth + 2, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "hd"."workspaces" r WHERE coalesce((open_queue), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{open_queue}';
  END;
END $f$;

