CREATE FUNCTION authz_int."user__self__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "hd"."users" w WHERE w."id" = p_id AND coalesce((active), false)) THEN
    RETURN NEXT pad || 'no   user ' || p_id || ' fails the type''s where {' || 'active' || '}';
    RETURN;
  END IF;
  IF p_id IN (SELECT r."id" AS id FROM "hd"."users" r WHERE r."id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || CASE WHEN p_asker IS NULL THEN 'self: id is you' ELSE 'self: id is them' END || '';
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'user.self';
END $f$;

