BEGIN
  IF p_id IN (SELECT g.object_id::uuid AS id FROM authz.shares g WHERE g.object_type = 'ticket' AND g.relation = ANY ((SELECT authz_int.role_relations('ticket', 'work'))::text[]) AND EXISTS (SELECT 1 FROM authz.roles ro WHERE 'role:' || ro.id = g.relation AND ro.owner_type = 'workspace' AND ro.owner_id IN (SELECT (w."workspace_id")::text FROM "hd"."tickets" w WHERE w."id" = g.object_id::uuid)) AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || CASE WHEN p_asker IS NULL THEN 'a custom role given to you' ELSE 'a custom role given to them' END || CASE WHEN p_asker IS NULL OR authz_int.asker_sees(p_asker, 'ticket', p_id::text, true) THEN coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') || coalesce(' (role ' || (SELECT ro.name FROM authz.roles ro WHERE 'role:' || ro.id = g.relation) || ')', '') FROM authz.shares g WHERE g.object_type = 'ticket' AND g.object_id = p_id::text AND g.relation = ANY ((SELECT authz_int.role_relations('ticket', 'work'))::text[]) AND EXISTS (SELECT 1 FROM authz.roles ro WHERE 'role:' || ro.id = g.relation AND ro.owner_type = 'workspace' AND ro.owner_id IN (SELECT (w."workspace_id")::text FROM "hd"."tickets" w WHERE w."id" = p_id)) AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '') ELSE '' END;
    RETURN;
  END IF;
  IF p_id IN (SELECT g.object_id::uuid AS id FROM authz.shares g WHERE g.object_type = 'ticket' AND g.relation = ANY ((SELECT authz_int.role_relations('ticket', 'work'))::text[]) AND EXISTS (SELECT 1 FROM authz.roles ro WHERE 'role:' || ro.id = g.relation AND ro.owner_type = 'workspace' AND ro.owner_id IN (SELECT (w."workspace_id")::text FROM "hd"."tickets" w WHERE w."id" = g.object_id::uuid)) AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    FOR v_t IN SELECT x.gid::text AS gid FROM (SELECT g.subject_id AS gid FROM authz.shares g WHERE g.object_type = 'ticket' AND g.object_id = p_id::text AND g.relation = ANY ((SELECT authz_int.role_relations('ticket', 'work'))::text[]) AND EXISTS (SELECT 1 FROM authz.roles ro WHERE 'role:' || ro.id = g.relation AND ro.owner_type = 'workspace' AND ro.owner_id IN (SELECT (w."workspace_id")::text FROM "hd"."tickets" w WHERE w."id" = p_id)) AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) x LIMIT 1 LOOP
      IF p_asker IS NOT NULL AND NOT authz_int.asker_sees(p_asker, 'team', v_t.gid, false) THEN
        RETURN NEXT pad || 'yes  ' || 'a custom role given to' || ' a team you can''t see';
        RETURN;
      END IF;
      RETURN NEXT pad || 'yes  ' || 'a custom role given to' || ' team ' || v_t.gid || CASE WHEN p_asker IS NULL THEN ', and you are member there' ELSE ', and they are member there' END;
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.gid::uuid, p_depth + 1, p_seen, p_asker);
    END LOOP;
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'ticket.role';
END $f$;

CREATE FUNCTION authz_int."ticket__work__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."ticket__work");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'ticket.work = ((assignee or team.member or team.oversee or roles) and workspace.agent) or workspace.work_all or responder';
  BEGIN
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "hd"."tickets" r
  WHERE r."id" IN ((SELECT id FROM authz_int."ticket__assignee")
  UNION ALL
  (SELECT id FROM authz_int."ticket__team__member")
  UNION ALL
  (SELECT id FROM authz_int."ticket__team__oversee")
  UNION ALL
  (SELECT id FROM authz_int."ticket__roles:work"))
    AND r."id" IN (SELECT id FROM authz_int."ticket__workspace__agent"));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '((assignee or team.member or team.oversee or a custom role) and workspace.agent)';
    v_ok := (p_id) IN ((SELECT id FROM authz_int."ticket__assignee")
  UNION ALL
  (SELECT id FROM authz_int."ticket__team__member")
  UNION ALL
  (SELECT id FROM authz_int."ticket__team__oversee")
  UNION ALL
  (SELECT id FROM authz_int."ticket__roles:work"));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(assignee or team.member or team.oversee or a custom role)';
    v_ok := (p_id) IN (SELECT id FROM authz_int."ticket__workspace__agent");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.agent';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."tickets" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'workspace', v_t.id, false) THEN
        RETURN NEXT pad || '  ' || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has agent' ELSE ', without agent' END;
      IF NOT ('workspace:agent:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."workspace__agent__why"(v_t.id::uuid, p_depth + 2 + 1, p_seen || ('workspace:agent:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT id FROM authz_int."ticket__workspace__work_all");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.work_all';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."tickets" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'workspace', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has work_all' ELSE ', without work_all' END;
      IF NOT ('workspace:work_all:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."workspace__work_all__why"(v_t.id::uuid, p_depth + 1 + 1, p_seen || ('workspace:work_all:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT id FROM authz_int."ticket__responder");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'responder';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."ticket__responder__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
  END;
END $f$;

CREATE FUNCTION authz_int."ticket__reply__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
