  (SELECT id FROM authz_int."ticket__cc"))
    AND r."id" IN (SELECT id FROM authz_int."ticket__workspace__member"));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '((requester or cc) and workspace.member)';
    v_ok := (p_id) IN ((SELECT id FROM authz_int."ticket__requester")
  UNION ALL
  (SELECT id FROM authz_int."ticket__cc"));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(requester or cc)';
    v_ok := (p_id) IN (SELECT id FROM authz_int."ticket__workspace__member");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.member';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."tickets" r WHERE r."id" = p_id AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'workspace', v_t.id, false) THEN
        RETURN NEXT pad || '  ' || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has member' ELSE ', without member' END;
      IF NOT ('workspace:member:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."workspace__member__why"(v_t.id::uuid, p_depth + 2 + 1, p_seen || ('workspace:member:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

