END $f$;

CREATE FUNCTION authz_int."comment__author__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT r."id" AS id FROM "hd"."comments" r WHERE r."author_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || CASE WHEN p_asker IS NULL THEN 'author: author_id is you' ELSE 'author: author_id is them' END || '';
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'comment.author';
END $f$;

CREATE FUNCTION authz_int."comment__via__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT r."id" AS id FROM "hd"."comments" r WHERE r."integration_id" = (SELECT authz_int."integration__me"())) THEN
    RETURN NEXT pad || 'yes  ' || CASE WHEN p_asker IS NULL THEN 'via: integration_id is you' ELSE 'via: integration_id is them' END || '';
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'comment.via';
END $f$;

CREATE FUNCTION authz_int."comment__view__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."comment__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'comment.view = ticket.work or (ticket.view and {not internal})';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."comment__ticket__work");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'ticket.work';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."ticket_id" AS id FROM "hd"."comments" r WHERE r."id" = p_id AND r."ticket_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'ticket', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'ticket is a ticket you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'ticket is ticket '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has work' ELSE ', without work' END;
      IF NOT ('ticket:work:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."ticket__work__why"(v_t.id::uuid, p_depth + 1 + 1, p_seen || ('ticket:work:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "hd"."comments" r
  WHERE r."id" IN (SELECT id FROM authz_int."comment__ticket__view")
    AND coalesce((not internal), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(ticket.view and {not internal})';
    v_ok := (p_id) IN (SELECT id FROM authz_int."comment__ticket__view");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'ticket.view';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."ticket_id" AS id FROM "hd"."comments" r WHERE r."id" = p_id AND r."ticket_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'ticket', v_t.id, false) THEN
        RETURN NEXT pad || '  ' || '       ' || 'ticket is a ticket you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'ticket is ticket '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has view' ELSE ', without view' END;
      IF NOT ('ticket:view:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."ticket__view__why"(v_t.id::uuid, p_depth + 2 + 1, p_seen || ('ticket:view:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "hd"."comments" r WHERE coalesce((not internal), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{not internal}';
  END;
END $f$;

-- What explain may show of an object while it walks as another user (p_asker: the one asking, as user id,
-- principal type and scopes; NULL: they ask of themselves): whether the one asking sees it or, p_inspect, may inspect
-- it (list its shares). It asks as them, then puts back the user explained.
CREATE FUNCTION authz_int.asker_sees(p_asker text[], p_type text, p_id text, p_inspect boolean) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_user text := coalesce(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_ok boolean;
BEGIN
  IF p_asker IS NULL THEN RETURN authz_int.visible(p_type, p_id); END IF;   -- (asked only whether they see it)
  IF authz_int.caller_is_admin() THEN RETURN true; END IF;
  PERFORM set_config('authz.user_id', p_asker[1], true);
  PERFORM set_config('authz.principal_type', p_asker[2], true);
  PERFORM set_config('authz.scopes', p_asker[3], true);
  PERFORM authz_int.sign();
  v_ok := CASE WHEN p_inspect THEN authz_int.may_inspect(p_type, p_id) ELSE authz_int.visible(p_type, p_id) END;
  PERFORM set_config('authz.user_id', v_user, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
  RETURN v_ok;
END $f$;

-- Why the current user (or, for people who may inspect the object, another user) holds a
-- permission, or what is missing: SELECT * FROM authz.explain('file', 11, 'edit')
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id text, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_ok boolean; v_text text; v_uuid uuid;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), '');
        v_asker text[];   -- for another user: the one asking, whose sight the walk keeps to
BEGIN
  -- the signed-in user's own id is the signed-in user: asked as without it (a service whose id is a user's is not)
  IF p_user IS NOT NULL AND authz_int.canon('user', p_user) IS NOT DISTINCT FROM authz.uid()::text THEN
    p_user := NULL;
  END IF;
  -- another user's access: only for people who may inspect the object, within their scopes (as authz.who)
  IF p_user IS NOT NULL AND (NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm)) THEN
    RAISE EXCEPTION 'you cannot inspect access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- people who can't see the object learn nothing about it, whatever else they hold on it (as for a missing one)
  IF p_user IS NULL AND NOT authz_int.may_inspect(p_type, p_id) AND NOT authz_int.visible(p_type, p_id) THEN
    RETURN NEXT 'no   you have no access to ' || p_type || ' ' || p_id;
    RETURN;
  END IF;
  IF p_user IS NOT NULL THEN
    v_asker := ARRAY[v_me, v_pt, v_scopes];
    PERFORM set_config('authz.user_id', p_user, true);
    PERFORM set_config('authz.principal_type', '', true);
    PERFORM set_config('authz.scopes', '', true);   -- that user's access, with full rights (as authz.who)
    PERFORM authz_int.sign();
  END IF;
  v_ok := authz.can(p_type, p_id, p_perm);
  RETURN NEXT CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || coalesce(coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || nullif(current_setting('authz.user_id', true), ''), 'nobody')
    || ' ' || CASE WHEN v_ok THEN 'holds ' ELSE 'does not hold ' END || p_perm || ' on ' || p_type || ' ' || p_id;
  <<asking>> BEGIN
  CASE p_type
    WHEN 'workspace' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage' THEN RETURN QUERY SELECT * FROM authz_int."workspace__manage__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'manage_roles' THEN RETURN QUERY SELECT * FROM authz_int."workspace__manage_roles__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'work_all' THEN RETURN QUERY SELECT * FROM authz_int."workspace__work_all__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'work' THEN RETURN QUERY SELECT * FROM authz_int."workspace__work__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."workspace__view__why"(v_uuid, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'impersonate' THEN RETURN QUERY SELECT * FROM authz_int."user__impersonate__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'see_notes' THEN RETURN QUERY SELECT * FROM authz_int."user__see_notes__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'org_tickets' THEN RETURN QUERY SELECT * FROM authz_int."user__org_tickets__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."user__view__why"(v_uuid, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'integration' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage_keys' THEN RETURN QUERY SELECT * FROM authz_int."integration__manage_keys__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."integration__view__why"(v_uuid, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'customer_org' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'see_tickets' THEN RETURN QUERY SELECT * FROM authz_int."customer_org__see_tickets__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'manage' THEN RETURN QUERY SELECT * FROM authz_int."customer_org__manage__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."customer_org__view__why"(v_uuid, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'oversee' THEN RETURN QUERY SELECT * FROM authz_int."team__oversee__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'manage' THEN RETURN QUERY SELECT * FROM authz_int."team__manage__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."team__view__why"(v_uuid, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'leadership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."leadership__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."leadership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'support_grant' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."support_grant__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."support_grant__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'ticket' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'work' THEN RETURN QUERY SELECT * FROM authz_int."ticket__work__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'reply' THEN RETURN QUERY SELECT * FROM authz_int."ticket__reply__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."ticket__view__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'manage' THEN RETURN QUERY SELECT * FROM authz_int."ticket__manage__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'share' THEN RETURN QUERY SELECT * FROM authz_int."ticket__share__why"(v_uuid, 1, '{}', v_asker);
        WHEN 'break_glass' THEN RETURN QUERY SELECT * FROM authz_int."ticket__break_glass__why"(v_uuid, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'comment' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."comment__view__why"(v_uuid, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

REVOKE SELECT ON ALL TABLES IN SCHEMA authz_gen, authz_int FROM "hd_app";
GRANT SELECT ON authz_gen.policy_lines, authz_int."customer_org__member", authz_int."customer_org__view", authz_int."team__lead", authz_int."team__manage", authz_int."team__member", authz_int."team__oversee", authz_int."team__view", authz_int."ticket__cc", authz_int."ticket__reply", authz_int."ticket__responder", authz_int."ticket__roles:work", authz_int."ticket__view", authz_int."ticket__work", authz_int."user__org_tickets", authz_int."user__self", authz_int."workspace__admin", authz_int."workspace__agent", authz_int."workspace__connected", authz_int."workspace__manage", authz_int."workspace__member", authz_int."workspace__view", authz_int."workspace__work", authz_int."workspace__work_all" TO "hd_app";

-- The sync role reads the index, and nothing else rowstile keeps
DO $sr$
DECLARE v_sync oid := to_regrole('"hd_electric"'); v_app oid := to_regrole('"hd_app"'); v_cols text;
BEGIN
  IF v_sync IS NULL THEN
    RAISE EXCEPTION 'the sync role hd_electric does not exist [AZ808]'
      USING HINT = 'make it for the engine: CREATE ROLE hd_electric LOGIN REPLICATION BYPASSRLS, then apply again';
  END IF;
  IF pg_catalog.pg_has_role(v_sync, CURRENT_USER, 'MEMBER') THEN
    RAISE EXCEPTION 'the sync role hd_electric is the role that applies the policy (%), or a member of it [AZ808]', CURRENT_USER
      USING HINT = 'the engine connects as a role of its own, which owns nothing of the database';
  END IF;
  IF v_app IS NOT NULL AND (pg_catalog.pg_has_role(v_sync, v_app, 'MEMBER') OR pg_catalog.pg_has_role(v_app, v_sync, 'MEMBER')) THEN
    RAISE EXCEPTION 'the sync role hd_electric and the app role hd_app are one another''s members: the app would read every row [AZ808]'
      USING HINT = 'the engine connects as a role of its own, which the app role is not a member of, nor it of the app role';
  END IF;
  SELECT pg_catalog.string_agg(m.tbl || '.' || m.col, ', ' ORDER BY m.tbl, m.col) INTO v_cols FROM authz_int.masked_columns m
  WHERE pg_catalog.has_column_privilege(v_sync, m.tbl, m.col, 'SELECT');
  IF v_cols IS NOT NULL THEN
    RAISE EXCEPTION 'the sync role hd_electric may read masked columns: % [AZ809]', v_cols
      USING HINT = 'it reads every row, so a masked column would reach every client: revoke SELECT on the table, grant the other columns (GRANT SELECT (id, name) ON ...), then apply again';
  END IF;
END $sr$;
GRANT USAGE ON SCHEMA authz_sync TO "hd_electric";
GRANT SELECT ON ALL TABLES IN SCHEMA authz_sync TO "hd_electric";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."customer_org__member"', 'authz_int."customer_org__view"', 'authz_int."team__lead"', 'authz_int."team__manage"', 'authz_int."team__member"', 'authz_int."team__oversee"', 'authz_int."team__view"', 'authz_int."ticket__cc"', 'authz_int."ticket__reply"', 'authz_int."ticket__responder"', 'authz_int."ticket__roles:work"', 'authz_int."ticket__view"', 'authz_int."ticket__work"', 'authz_int."user__org_tickets"', 'authz_int."user__self"', 'authz_int."workspace__admin"', 'authz_int."workspace__agent"', 'authz_int."workspace__connected"', 'authz_int."workspace__manage"', 'authz_int."workspace__member"', 'authz_int."workspace__view"', 'authz_int."workspace__work"', 'authz_int."workspace__work_all"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"hd_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"hd_app"'::regrole
